-- GENERATED by benchmarks/tpch/scripts/qualify_queries.py from ../queries — do not edit.
-- Mixed layout: dimensions in postgresql.tpch_mixed, facts in hive.tpch.
-- TPC-H Q21: Suppliers Who Kept Orders Waiting — standard form
SELECT
    s_name,
    COUNT(*) AS numwait
FROM postgresql.tpch_mixed.supplier
JOIN hive.tpch.lineitem l1 ON s_suppkey = l1.l_suppkey
JOIN hive.tpch.orders ON o_orderkey = l1.l_orderkey
JOIN postgresql.tpch_mixed.nation ON s_nationkey = n_nationkey
WHERE o_orderstatus = 'F'
    AND l1.l_receiptdate > l1.l_commitdate
    AND EXISTS (
        SELECT *
        FROM hive.tpch.lineitem l2
        WHERE l2.l_orderkey = l1.l_orderkey
            AND l2.l_suppkey <> l1.l_suppkey
    )
    AND NOT EXISTS (
        SELECT *
        FROM hive.tpch.lineitem l3
        WHERE l3.l_orderkey = l1.l_orderkey
            AND l3.l_suppkey <> l1.l_suppkey
            AND l3.l_receiptdate > l3.l_commitdate
    )
    AND n_name = 'SAUDI ARABIA'
GROUP BY s_name
ORDER BY numwait DESC, s_name
LIMIT 100
